/* eslint-disable */
/**
 * Rest-timer notifications, imported by the generated app-shell worker.
 * Kept separate from caching so the shell worker stays generated by the build.
 *
 * The page posts the rest deadline here; the worker owns the alarm, so a phone
 * that freezes the tab still gets the "rest is over" notification.
 *
 * One notification only, at the end: a live countdown on the lock screen meant
 * re-showing the banner every few seconds, which reads as spam on iOS. While
 * resting the worker stays quiet; the deadline is persisted in a cache so a
 * worker the browser recycled can re-arm (or fire late) as soon as it wakes.
 */
(function () {
  var TAG = "forja-rest";
  var STATE_CACHE = "forja-rest-state";
  var STATE_URL = "/__forja-rest-state.json";
  var endTimer = null;
  var state = null;

  function clearTimers() {
    if (endTimer) clearTimeout(endTimer);
    endTimer = null;
  }

  // A cancel and the reschedule that follows it arrive back to back, so the
  // writes are chained: the last one posted is the one left in the cache.
  var writes = Promise.resolve();

  function persist(next) {
    writes = writes.then(function () {
      return caches
        .open(STATE_CACHE)
        .then(function (cache) {
          if (!next) return cache.delete(STATE_URL);
          return cache.put(
            STATE_URL,
            new Response(JSON.stringify(next), {
              headers: { "content-type": "application/json" },
            }),
          );
        })
        .catch(function () {});
    });
    return writes;
  }

  function restore() {
    return writes
      .then(function () {
        return caches.open(STATE_CACHE);
      })
      .then(function (cache) {
        return cache.match(STATE_URL);
      })
      .then(function (res) {
        return res ? res.json() : null;
      })
      .catch(function () {
        return null;
      });
  }

  function closeRest() {
    return self.registration
      .getNotifications({ tag: TAG })
      .then(function (list) {
        list.forEach(function (n) {
          n.close();
        });
      })
      .catch(function () {});
  }

  /** Wake any live page so it can beep even if its own timer was throttled. */
  function beepClients() {
    return self.clients
      .matchAll({ type: "window", includeUncontrolled: true })
      .then(function (list) {
        list.forEach(function (client) {
          client.postMessage({ type: "rest-done" });
        });
      })
      .catch(function () {});
  }

  function showDone() {
    if (!state) return Promise.resolve();
    var data = state;
    state = null;
    clearTimers();
    return Promise.all([
      persist(null),
      beepClients(),
      self.registration
        .showNotification(data.title || "Rest is over", {
          body: data.body || "",
          tag: TAG,
          renotify: true,
          // Explicit: this is the one alert of the rest, and it must be heard.
          silent: false,
          requireInteraction: true,
          vibrate: [400, 150, 400, 150, 600],
          data: { url: data.url || "/sessao" },
          icon: "/icon-192.png",
          badge: "/icon-192.png",
        })
        .catch(function () {}),
    ]);
  }

  /** Arm (or fire) the end alarm for the current state. */
  function arm() {
    clearTimers();
    if (!state) return Promise.resolve();
    var ms = state.endsAt - Date.now();
    if (ms <= 0) return showDone();
    endTimer = setTimeout(function () {
      void showDone();
    }, ms);
    return Promise.resolve();
  }

  /**
   * Heartbeat from the page: the browser may recycle this worker mid-rest, so
   * every ping re-reads the persisted deadline and re-arms, firing right away
   * when the rest already ended while the worker was asleep.
   */
  function resync() {
    if (state) return arm();
    return restore().then(function (saved) {
      if (!saved || !saved.endsAt) return;
      state = saved;
      return arm();
    });
  }

  self.addEventListener("message", function (event) {
    var msg = event.data || {};
    if (msg.type === "rest-schedule") {
      clearTimers();
      state = {
        endsAt: msg.endsAt,
        title: msg.title,
        body: msg.body,
        url: msg.url,
      };
      event.waitUntil(Promise.all([persist(state), closeRest(), arm()]));
    } else if (msg.type === "rest-ping") {
      event.waitUntil(resync());
    } else if (msg.type === "rest-cancel") {
      state = null;
      clearTimers();
      event.waitUntil(Promise.all([persist(null), closeRest()]));
    }
  });

  self.addEventListener("notificationclick", function (event) {
    if (!event.notification || event.notification.tag !== TAG) return;
    event.notification.close();
    var url = (event.notification.data && event.notification.data.url) || "/sessao";
    event.waitUntil(
      self.clients.matchAll({ type: "window", includeUncontrolled: true }).then(function (list) {
        for (var i = 0; i < list.length; i++) {
          if ("focus" in list[i]) return list[i].focus();
        }
        return self.clients.openWindow(url);
      }),
    );
  });
})();
